const https = require('https');

// Get app credentials from openclaw.json
const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/.openclaw/openclaw.json', 'utf8'));
const appId = config.channels.feishu.accounts.main.appId;
const appSecret = config.channels.feishu.accounts.main.appSecret;

// Get tenant access token
function getToken() {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify({ app_id: appId, app_secret: appSecret });
    const opts = {
      hostname: 'open.feishu.cn',
      path: '/open-apis/auth/v3/tenant_access_token/internal',
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
    };
    const req = https.request(opts, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => resolve(JSON.parse(d).tenant_access_token));
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

// Fetch document blocks
function getDoc(token, docToken) {
  return new Promise((resolve, reject) => {
    const opts = {
      hostname: 'open.feishu.cn',
      path: `/open-apis/docx/v1/documents/${docToken}/blocks?page_size=50`,
      method: 'GET',
      headers: { 'Authorization': `Bearer ${token}` }
    };
    const req = https.request(opts, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => {
        const json = JSON.parse(d);
        if (json.code !== 0) return reject(new Error(json.msg));
        resolve(json.data);
      });
    });
    req.on('error', reject);
    req.end();
  });
}

async function main() {
  const token = await getToken();
  const docId = 'OenYdVR41oJs9PxBlSicZPmnnYO';
  const data = await getDoc(token, docId);

  // Extract text from blocks
  function extractText(block, depth = 0) {
    const indent = '  '.repeat(depth);
    let result = '';
    if (block.block_type === 2 || block.block_type === 3) { // paragraph or text
      const elements = block.text?.elements || [];
      for (const el of elements) {
        result += el.text_run?.content || '';
      }
    }
    result += '\n';
    // Children
    const children = block.children || [];
    for (const childId of children) {
      const child = data.items?.find(b => b.block_id === childId);
      if (child) result += indent + extractText(child, depth + 1);
    }
    return result;
  }

  for (const block of data.items || []) {
    if (!block.parent_id || block.parent_id === docId) {
      process.stdout.write(extractText(block));
    }
  }
}

main().catch(console.error);
